void init_crc16_poly(void) {
    unsigned short *table = (unsigned short *)0x00402010;
    for (int i = 0; i < 256; i++) {
        unsigned short cur = (unsigned short)(i << 8);
        for (int j = 0; j < 8; j++) {
            if (cur & 0x8000) cur = (cur << 1) ^ 0x1021;
            else cur = cur << 1;
        }
        table[i] = cur;
    }
}

int verify_crc16_checksum(unsigned char *param_1, int param_2, unsigned short param_3) {
    unsigned short crc = 0xFFFF;
    unsigned short *table = (unsigned short *)0x00402010;
    for (int i = 0; i < param_2; i++) {
        unsigned char idx = (unsigned char)((crc >> 8) ^ param_1[i]);
        crc = (unsigned short)((crc << 8) ^ table[idx]);
    }
    return (crc == param_3) ? 1 : 0;
}

int validate_sync_word(unsigned char *param_1) {
    unsigned char *sync = (unsigned char *)0x00402100;
    for (int i = 0; i < 4; i++) {
        if (param_1[i] != sync[i]) return 0;
    }
    return 1;
}

void decode_sensor_telemetry(long param_1, float *param_2) {
    float *calib = (float *)0x00402090;
    float raw_alt = (float)*(unsigned int *)(param_1 + 0x08);
    param_2[0] = (raw_alt * calib[0]) + calib[1]; /* Altitude in km */
    float raw_v = (float)*(unsigned short *)(param_1 + 0x0C);
    param_2[1] = (raw_v * calib[3]) + calib[4];   /* Battery volts */
    float raw_t = (float)*(short *)(param_1 + 0x0E);
    param_2[2] = (raw_t * calib[6]) + calib[7];   /* Temp Celsius */
}

int process_downlink_stream(unsigned char *param_1, int param_2, float *param_3) {
    if (param_2 < 48) return -1;
    if (validate_sync_word(param_1) == 0) return -2;
    unsigned short packet_crc = *(unsigned short *)(param_1 + 16);
    if (verify_crc16_checksum(param_1, 16, packet_crc) == 0) return -3;
    decode_sensor_telemetry((long)param_1, param_3);
    return 0;
}
